// Profile: host-chat. One manually triggered broadcast, not an event subscription.
import { host } from "host";
console.log(JSON.stringify(await host.chat.broadcast("Hello from the sandbox")));

// Profile: none. Top-level source executes once.
console.log("Hello from the restricted sandbox");
console.log(2 + 2);

// Profile: none. A caught denial can still leave permission observations.
try {
  await Deno.readTextFile("/etc/hosts");
} catch {
  console.log("Read was blocked, but the script continued");
}
